    {
      "kind": "foreach",
      "name": "inspect_all",
      "description": "Inspect schema of each quarterly sales CSV file",
      "over": "inputs",
      "body": {
        "kind": "primitive",
        "name": "inspect_schema",
        "capability": "csv.inspect_schema",
        "code": {"path": "${item}"},
        "inputBindings": [],
        "output": {
          "name": "schema_report",
          "typeName": "Record",
          "fields": [
            {"name": "file", "typeName": "String"},
            {"name": "columns", "typeName": "List<String>"},
            {"name": "row_count", "typeName": "Integer"},
            {"name": "issues", "typeName": "List<String>"}
          ]
        }
