      "kind": "foreach",
      "name": "detect_all",
      "description": "Detect data-quality issues in each file",
      "over": "inputs",
      "body": {
        "kind": "primitive",
        "name": "detect_issues",
        "capability": "execute_python",
        "code": "import pandas as pd\ndf = pd.read_csv(\"${item}\")\nissues = []\nmissing = df.isnull().sum().to_dict()\nif any(v > 0 for v in missing.values()):\n    issues.append(f\"Missing values: {missing}\")\ndupes = df.duplicated().sum()\nif dupes > 0:\n    issues.append(f\"Duplicate rows: {dupes}\")\nfor col in df.select_dtypes(include=['number']).columns:\n    q1 = df[col].quantile(0.25)\n    q3 = df[col].quantile(0.75)\n    iqr = q3 - q1\n    outliers = ((df[col] < q1 - 1.5*iqr) | (df[col] > q3 + 1.5*iqr)).sum()\n    if outliers > 0:\n        issues.append(f\"Outliers in {col}: {outliers}\")\nenv[\"file\"] = \"${item}\"\nenv[\"type_errors\"] = []\nenv[\"missing_values\"] = missing\nenv[\"duplicates\"] = dupes\nenv[\"outliers\"] = issues\nenv[\"schema_drift\"] = []",
        "inputBindings": [],
        "output": {
          "name": "issue_report",
          "typeName": "Record",
          "fields": [
            {"name": "file", "typeName": "String"},
            {"name": "type_errors", "typeName": "List<String>"},
            {"name": "missing_values", "typeName": "Record"},
            {"name": "duplicates", "typeName": "Integer"},
            {"name": "outliers", "typeName": "List<String>"},
            {"name": "schema_drift", "typeName": "List<String>"}
