        "kind": "primitive",
        "name": "repair_file",
        "capability": "execute_python",
        "code": "import pandas as pd\nimport os\ndf = pd.read_csv(\"${item}\")\nrepairs = []\nbefore = len(df)\ndf = df.drop_duplicates()\nif len(df) < before:\n    repairs.append(f\"Dropped {before - len(df)} duplicate rows\")\nfor col in df.select_dtypes(include=['number']).columns:\n    if df[col].isnull().any():\n        df[col] = df[col].fillna(df[col].median())\n        repairs.append(f\"Filled missing values in {col} with median\")\nbase = os.path.basename(\"${item}\")\nrepaired_path = \"repaired_\" + base\ndf.to_csv(repaired_path, index=False)\nenv[\"original_file\"] = \"${item}\"\nenv[\"repaired_path\"] = repaired_path\nenv[\"columns\"] = list(df.columns)\nenv[\"repairs_made\"] = repairs",
        "inputBindings": [],
        "output": {
          "name": "repair_report",
          "typeName": "Record",
          "fields": [
            {"name": "original_file", "typeName": "String"},
            {"name": "repaired_path", "typeName": "String"},
            {"name": "columns", "typeName": "List<String>"},
            {"name": "repairs_made", "typeName": "List<String>"}
