      "kind": "foreach",
      "name": "revalidate_all",
      "description": "Revalidate repaired files by re-inspecting schema",
      "over": "repair_all",
      "body": {
        "kind": "primitive",
        "name": "revalidate_schema",
        "capability": "csv.inspect_schema",
        "code": {"path": "${item.repaired_path}"},
        "inputBindings": [],
        "output": {
          "name": "revalidation_report",
          "typeName": "Record",
          "fields": [
            {"name": "file", "typeName": "String"},
            {"name": "columns", "typeName": "List<String>"},
            {"name": "row_count", "typeName": "Integer"},
            {"name": "issues", "typeName": "List<String>"}
          ]
        }
      },
      "output": {
        "name": "all_revalidations",
        "typeName": "List<Record>"
      }
    },
    {
      "kind": "foreach",
      "name": "stats_all",
      "description": "Compute quarterly statistics for each repaired file",
      "over": "repair_all",
      "body": {
        "kind": "primitive",
        "name": "compute_stats",
        "capability": "execute_python",
        "code": "import pandas as pd\ndf = pd.read_csv(\"${item.repaired_path}\")\nnumeric_cols = df.select_dtypes(include=['number']).columns.tolist()\nstats = {}\nfor col in numeric_cols:\n    stats[col] = {\n        \"sum\": float(df[col].sum()),\n        \"mean\": float(df[col].mean()),\n        \"median\": float(df[col].median()),\n        \"std\": float(df[col].std()),\n        \"min\": float(df[col].min()),\n        \"max\": float(df[col].max()),\n        \"count\": int(df[col].count())\n    }\nenv[\"file\"] = \"${item.repaired_path}\"\nenv[\"columns\"] = ${item.columns}\nenv[\"numeric_stats\"] = stats\nenv[\"total_rows\"] = len(df)\nenv[\"total_columns\"] = len(df.columns)",
        "inputBindings": [],
        "output": {
          "name": "stats_report",
          "typeName": "Record",
          "fields": [
            {"name": "file", "typeName": "String"},
            {"name": "columns", "typeName": "List<String>"},
            {"name": "numeric_stats", "typeName": "Record"},
            {"name": "total_rows", "typeName": "Integer"},
            {"name": "total_columns", "typeName": "Integer"}
          ]
        }
      },
      "output": {
        "name": "all_stats",
        "typeName": "List<Record>"
      }
    },
    {
      "kind": "primitive",
      "name": "merge_results",
      "description": "Merge all quarterly results into a single dataset",
      "capability": "execute_python",
      "code": "merged = {\n    \"schemas\": ${all_schemas},\n    \"issues\": ${all_issues},\n    \"repairs\": ${all_repairs},\n    \"revalidations\": ${all_revalidations},\n    \"statistics\": ${all_stats}\n}\nenv[\"merged_data\"] = merged\nenv[\"quarterly_count\"] = len(${all_stats})",
