        {"param": "schemas", "source": "inspect_all", "binding": "all_schemas"},
        {"param": "issues", "source": "detect_all", "binding": "all_issues"},
        {"param": "repairs", "source": "repair_all", "binding": "all_repairs"},
        {"param": "revalidations", "source": "revalidate_all", "binding": "all_revalidations"},
        {"param": "statistics", "source": "stats_all", "binding": "all_stats"}
      ],
      "output": {
        "name": "merged",
        "typeName": "Record",
        "fields": [
          {"name": "schemas", "typeName": "List<Record>"},
          {"name": "issues", "typeName": "List<Record>"},
          {"name": "repairs", "typeName": "List<Record>"},
          {"name": "revalidations", "typeName": "List<Record>"},
          {"name": "statistics", "typeName": "List<Record>"},
          {"name": "quarterly_count", "typeName": "Integer"}
        ]
      }
