      "capability": "execute_python",
      "code": "merged = ${merged}\nreview = {\n    \"total_quarters\": merged[\"quarterly_count\"],\n    \"total_issues_detected\": sum(len(r.get(\"missing_values\", {})) + r.get(\"duplicates\", 0) for r in merged[\"issues\"]),\n    \"total_repairs_made\": sum(len(r.get(\"repairs_made\", [])) for r in merged[\"repairs\"]),\n    \"revalidation_passed\": all(len(r.get(\"issues\", [])) == 0 for r in merged[\"revalidations\"]),\n    \"columns_across_quarters\": list(set().union(*[set(r.get(\"columns\", [])) for r in merged[\"statistics\"]])),\n    \"overall_quality_score\": 0.0\n}\nif review[\"revalidation_passed\"]:\n    review[\"overall_quality_score\"] = max(0, 100 - review[\"total_issues_detected\"] * 5)\nenv[\"review_result\"] = review",
