          {"name": "total_repairs_made", "typeName": "Integer"},
          {"name": "revalidation_passed", "typeName": "Boolean"},
          {"name": "columns_across_quarters", "typeName": "List<String>"},
          {"name": "overall_quality_score", "typeName": "Number"}
        ]
      }
    },
