      "inputBindings": [
        {"param": "merged", "source": "merge_results", "binding": "merged"},
        {"param": "review", "source": "quality_review", "binding": "review"}
      ],
      "output": {
        "name": "report",
        "typeName": "String"
      }
    }
  ],
  "dataFlow": [
    {"fromStep": "inspect_all", "toStep": "merge_results", "binding": "all_schemas"},
    {"fromStep": "detect_all", "toStep": "merge_results", "binding": "all_issues"},
    {"fromStep": "repair_all", "toStep": "revalidate_all", "binding": "all_repairs"},
    {"fromStep": "repair_all", "toStep": "stats_all", "binding": "all_repairs"},
    {"fromStep": "repair_all", "toStep": "merge_results", "binding": "all_repairs"},
    {"fromStep": "revalidate_all", "toStep": "merge_results", "binding": "all_revalidations"},
    {"fromStep": "stats_all", "toStep": "merge_results", "binding": "all_stats"},
    {"fromStep": "merge_results", "toStep": "quality_review", "binding": "merged"},
    {"fromStep": "merge_results", "toStep": "generate_report", "binding": "merged"},
    {"fromStep": "quality_review", "toStep": "generate_report", "binding": "review"}
